actions.action:
pcn_spolocnost: f.pcn_spolocnost, pcn_sidlo: f.pcn_sidlo,
pcn_strav_5_12: f.pcn_strav_5_12, pcn_strav_12_18: f.pcn_strav_12_18,
pcn_strav_nad_18: f.pcn_strav_nad_18, pcn_zraz_ranajky: f.pcn_zraz_ranajky,
pcn_zraz_obed: f.pcn_zraz_obed, pcn_zraz_vecera: f.pcn_zraz_vecera,
pcn_km_auto: f.pcn_km_auto, pcn_km_motocykel: f.pcn_km_motocykel,
pcn_koef_phm: f.pcn_koef_phm, pcn_harok: f.pcn_harok, pcn_mapovanie: f.pcn_mapovanie;

// Case sa pri novej verzii siete zaklada nanovo (inak by na nom chybali nove
// polia). Sadzby su UDAJ, nie odraz nicoho, takze sa musia preniest - bez toho
// by kazdy re-import ticho vratil hodnoty na default a prislo by sa na to az
// na vyuctovani, ktore vyslo inak nez minuly mesiac.
def stary = najnovsiCase("hr/cesty/pc_nastavenia")
def predch = (stary != null && stary.stringId != useCase.stringId) ? stary : null
def prev = { String id, def dflt ->
    def v = predch?.dataSet?.get(id)?.value
    return v != null ? v : dflt
}

change pcn_spolocnost   value { prev("pcn_spolocnost", "Netgrif, s.r.o.") as String }
// pflang:off  - adresa slovenskej firmy a nazov harku v cudzom zosite; oboje
// ide do tlaciva tak, ako je, a prelozit sa nema co
change pcn_sidlo        value { prev("pcn_sidlo", "Dúbravská cesta 14, Bratislava, 841 04") as String }
change pcn_strav_5_12   value { (prev("pcn_strav_5_12", 9.30d) as Number).doubleValue() }
change pcn_strav_12_18  value { (prev("pcn_strav_12_18", 13.80d) as Number).doubleValue() }
change pcn_strav_nad_18 value { (prev("pcn_strav_nad_18", 20.60d) as Number).doubleValue() }
change pcn_zraz_ranajky value { (prev("pcn_zraz_ranajky", 25.0d) as Number).doubleValue() }
change pcn_zraz_obed    value { (prev("pcn_zraz_obed", 40.0d) as Number).doubleValue() }
change pcn_zraz_vecera  value { (prev("pcn_zraz_vecera", 35.0d) as Number).doubleValue() }
change pcn_km_auto      value { (prev("pcn_km_auto", 0.313d) as Number).doubleValue() }
change pcn_km_motocykel value { (prev("pcn_km_motocykel", 0.09d) as Number).doubleValue() }
change pcn_koef_phm     value { (prev("pcn_koef_phm", 1.1d) as Number).doubleValue() }
change pcn_harok        value { prev("pcn_harok", "Tuzemská cesta") as String }
// pflang:on
change pcn_mapovanie    value { (prev("pcn_mapovanie", null) as String) ?: vychodzie_mapovanie() }

changeCaseProperty("title").about { "Travel expense settings" }
changeCaseProperty("color").about { "blue" }
postav_menu()

document.function:
{ def u ->
    // `?.` chrani pred null, nie pred chybajucou property - a na chybajucej
    // vyhodi MissingPropertyException uprostred akcie.
    return (u.hasProperty("fullName") && u.fullName) ? (u.fullName as String) : (u.email as String)
}

{ ->
    // Mapovanie pre tlacivo "Vyúčtovanie pracovných ciest od 01.01.2026".
    //
    // GEOMETRIA RIADKOV: jedna cesta zabera DVA riadky tlaciva - "Odchod"
    // a "Príchod". Zapis "C+1" preto znamena stlpec C v druhom riadku dvojice.
    // `prvy` je prvy datovy riadok, `krok` vyska jednej cesty, `max` pocet
    // ciest, ktore sa do tlaciva zmestia.
    //
    // ZAPISUJU SA LEN VSTUPY. Stlpce I (stravne), J (zakladna nahrada)
    // a L (nahrada za PHM) su vo vzorcoch tlaciva a zostavaju nedotknute -
    // po otvoreni v Exceli sa prepocitaju samy. Vynimka je K (priemerna cena
    // PHM): tam ma tlacivo vzorec, ktory ju hlada v tabulke tyzdennych cien
    // Statistickeho uradu, a tu cenu zadava ziadatel, takze ju prepiseme.
    return groovy.json.JsonOutput.prettyPrint(groovy.json.JsonOutput.toJson([
            hlavicka: [
                    spolocnost : "C4",
                    sidlo      : "C6",
                    obdobie    : "G4",
                    zamestnanec: "G6",
                    palivo     : "M2",
                    spotreba   : "M4",
                    spz        : "M6",
                    preddavok  : "M76"
            ],
            riadky  : [
                    prvy       : 12,
                    krok       : 2,
                    max        : 31,
                    datum      : "A",
                    cas_od     : "C",
                    cas_do     : "C+1",
                    miesto_zac : "D",
                    miesto_kon : "D+1",
                    rokovanie  : "E",
                    doprava    : "F",
                    strava     : "G",
                    km_tam     : "H",
                    km_spat    : "H+1",
                    cena_phm   : "K",
                    ubytovanie : "M",
                    ine        : "N"
            ],
            podpisy : [
                    zamestnanec : [bunka: "A78", sirka: 3, vyska: 3],
                    schvalovatel: [bunka: "D78", sirka: 3, vyska: 3]
            ]
    ]))
}

{ def id ->
    try { return findMenuItem(id) } catch (Exception e) { return null }
}

{ ->
    // Zobrazenie typu TASK, nie Case: otvori rovno formular. Dopyt NESMIE stat
    // na `processIdentifier` - task dokument ho nema, ma len `processId` razene
    // per verziu siete. Preto sa zuzuje na `transitionId` A `processId` TEJTO
    // verzie: `rebuildOnNewVersion` zaklada jeden case na verziu, takze bez
    // toho by zoznam po druhom re-importe ukazal dva riadky a clovek by
    // nevedel, ktory je ten platny.
    def id = "pc_nastavenia_view"
    def siet = "hr/cesty/pc_nastavenia"
    def nazov = i18n("Nastavenia pracovných ciest", ["en": "Travel expense settings"])
    try {
        def existing = menu_item(id)
        if (existing != null) {
            // Update cesta `createOrUpdateMenuItem` nefunguje, polozka sa vzdy
            // zahodi a postavi znova. PORADIE: najprv polozka, potom filter -
            // naopak to padne, lebo `deleteMenuItem` si filter este raz nacita.
            def current = getFilterFromMenuItem(existing)
            deleteMenuItem(existing)
            if (current != null) deleteFilter(current)
        }
        createOrUpdateMenuItem(
                id,
                "hr/cesty",              // URI cesta - musi sedet s uriNodes
                "Task",
                "transitionId:\"t_pcn\" AND processId:\"" +
                        (useCase.petriNetId as String) + "\"",
                "tune",
                nazov,
                [siet],
                ["spravca": siet],   // v menu ju vidi len spravca
                [:])
    } catch (Exception e) {
        // Menu nesmie zhodit zalozenie konfiguracneho casu - bez neho by appka
        // prisla aj o sadzby, nielen o polozku v menu.
        changeCaseProperty("color").about { "orange" }
    }
}

actions.action:
pcn_strav_5_12: f.pcn_strav_5_12, pcn_strav_12_18: f.pcn_strav_12_18,
pcn_strav_nad_18: f.pcn_strav_nad_18, pcn_km_auto: f.pcn_km_auto,
pcn_km_motocykel: f.pcn_km_motocykel, pcn_koef_phm: f.pcn_koef_phm,
pcn_mapovanie: f.pcn_mapovanie;

// Hodnoty a hlasky su po ANGLICKY - aplikacia ma anglictinu ako default
// a tieto retazce preklad nemaju (CLAUDE.md, Jazyk).
def kladne = { def pole, String co ->
    def v = pole.value
    if (v == null || (v as Number).doubleValue() <= 0) {
        throw new java.lang.IllegalStateException(co + " must be greater than zero.")
    }
    return (v as Number).doubleValue()
}
def s1 = kladne(pcn_strav_5_12, "The meal allowance for 5 to 12 hours")
def s2 = kladne(pcn_strav_12_18, "The meal allowance for 12 to 18 hours")
def s3 = kladne(pcn_strav_nad_18, "The meal allowance for over 18 hours")
kladne(pcn_km_auto, "The basic allowance per kilometre by car")
kladne(pcn_km_motocykel, "The basic allowance per kilometre by motorcycle")
kladne(pcn_koef_phm, "The fuel consumption coefficient")

// Pasma musia rast. Keby nerastli, dlhsia cesta by dala mensie stravne nez
// kratsia - a nikto by si toho nevsimol, lebo obe cisla by boli "nejake".
if (!(s1 <= s2 && s2 <= s3)) {
    throw new java.lang.IllegalStateException(
            "The meal allowance bands have to increase: 5-12 h <= 12-18 h <= over 18 h.")
}

// Mapovanie musi byt citatelny JSON, inak by sa to prejavilo az pri exporte
// - teda na cudzom vyuctovani, nie tu, kde to clovek prave pokazil.
def raw = ((pcn_mapovanie.value ?: "") as String).trim()
if (!raw) {
    throw new java.lang.IllegalStateException("The cell mapping cannot be empty.")
}
def mapa
try {
    mapa = new groovy.json.JsonSlurper().parseText(raw)
} catch (Exception e) {
    throw new java.lang.IllegalStateException("The cell mapping is not valid JSON: " + e.message)
}
["hlavicka", "riadky", "podpisy"].each { String kluc ->
    if (!(mapa instanceof Map) || mapa.get(kluc) == null) {
        throw new java.lang.IllegalStateException(
                "The cell mapping is missing the '" + kluc + "' section.")
    }
}

pcn_sablona: f.pcn_sablona, pcn_harok: f.pcn_harok,
pcn_vysledok: f.pcn_vysledok, pcn_ulozil: f.pcn_ulozil, pcn_ulozene_o: f.pcn_ulozene_o;

change pcn_ulozil value { kto(loggedUser()) }
change pcn_ulozene_o value { java.time.LocalDateTime.now() }
change pcn_vysledok value {
    def nazovSablony = pcn_sablona.value?.name
    return "sheet: " + ((pcn_harok.value ?: "(first)") as String) +
            ", form: " + (nazovSablony ? (nazovSablony as String) : "NOT UPLOADED - the xlsx export will not work")
}
